namespace SatisfactoryPlanner;
public partial class MainForm {
 internal void TestMaterials(){Opacity=0;ShowInTaskbar=false;Show();PreviewPage("Baukosten");Application.DoEvents();double power=plan!.Power,ore=plan.Raw["Desc_OreIron_C"];int machines=plan.Stages.Sum(s=>s.Count);var row=costs.Rows[0];string id=(string)row.Tag!;string required=(string)row.Cells[1].Value!;row.Cells[2].Value=true;Application.DoEvents();if(!settings.OwnedMaterials.Contains(id)||(string)row.Cells[3].Value! !="0")throw new Exception("Material checkbox failed.");Calculate();row=costs.Rows.Cast<DataGridViewRow>().Single(r=>(string)r.Tag! ==id);if(row.Cells[2].Value is not true||plan!.Power!=power||plan.Raw["Desc_OreIron_C"]!=ore||plan.Stages.Sum(s=>s.Count)!=machines)throw new Exception("Checklist affected production or lost its state.");var loaded=System.Text.Json.JsonSerializer.Deserialize<Settings>(System.Text.Json.JsonSerializer.Serialize(settings))!;if(!loaded.OwnedMaterials.Contains(id))throw new Exception("Checklist save/load failed.");row.Cells[2].Value=false;Application.DoEvents();if(settings.OwnedMaterials.Contains(id)||(string)row.Cells[3].Value! !=required)throw new Exception("Unchecking material failed.");Close();}
}
